def json_model_analysis_dump(framework_model: Model):
    def dump_partial_shape(shape: PartialShape):
        if shape.rank.is_dynamic:
            return 'None'
        dims = []
        for i in range(shape.rank.get_length()):
            dim = shape.get_dimension(i)
            dims.append(dim.get_length() if dim.is_static else 0)
        return dims

    def dump_element_type(ov_type):
        try:
            return str(get_dtype(ov_type))
        except Exception:  # pylint: disable=broad-except
            return 'None'

    json_dump = {}
    json_dump['inputs'] = {}
    for param in framework_model.get_parameters():
        param_name = param.get_friendly_name()
        json_dump['inputs'][param_name] = {
            'shape': dump_partial_shape(param.get_partial_shape()),
            'data_type': dump_element_type(param.get_element_type()),
            'value': 'None',  # data is not accessible
        }

    json_dump['intermediate'] = {}
    for output in framework_model.outputs:
        for name in output.get_names():
            json_dump['intermediate'][name] = {
                'shape': dump_partial_shape(output.get_partial_shape()),
                'data_type': dump_element_type(output.get_element_type()),
                'value': 'None',  # data is not accessible
            }

    json_model_analysis_print(json_dump)
